import urllib.request,re,html
for path in ['/download','/view/fibroxplorer-com/download']:
    url='https://www.fibroxplorer.com'+path if path.startswith('/') else path
    try:
        s=urllib.request.urlopen(urllib.request.Request(url,headers={'User-Agent':'Mozilla/5.0'}),timeout=30).read().decode('utf-8','replace')
        print('URL',url,'len',len(s))
        for pat in ['Mouse_SS_Fibro','RDS','drive.google','download','Mouse','Human']:
            ms=list(re.finditer(pat,s,re.I))
            print(pat,len(ms))
            for m in ms[:3]:
                print(s[max(0,m.start()-180):m.end()+220].replace('\\n',' ')[:600])
        links=sorted(set(re.findall(r'https?://["'^"'"\\']+', s)))
        print('links filtered')
        for l in links:
            if any(x in l.lower() for x in ['drive','rds','download','mouse','human','fibro']): print(html.unescape(l)[:500])
    except Exception as e: print('ERR',url,e)
PY"

